  const despues = ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 0, motivo: "merma detectada" });
  assert.equal(despues[1].tipo, "egreso");
  assert.equal(despues[1].cantidad, 10);
  assert.equal(stock(despues, "A1", "LPZ"), 0);
});

test("ajuste: si el recuento coincide no agrega nada", () => {
  const antes = conIngreso();
