test("RF-005-a: anular con motivo válido devuelve factura anulada con el motivo recortado", () => {
  const original = nueva();
  const a = anularFactura(original, "  Error en el NIT del cliente  ");
  assert.equal(a.estado, "anulada");
  assert.equal(a.motivo, "Error en el NIT del cliente");
  assert.equal(a.numero, original.numero);
});

test("RF-005-b: la original no cambia al anularse", () => {
  const original = nueva();
  anularFactura(original, "Error en el NIT del cliente");
  assert.equal(original.estado, "emitida");
  assert.ok(!("motivo" in original));
  assert.ok(Object.isFrozen(original));
});

test("RF-005-c: motivo ausente, vacío o menor a 10 caracteres sin bordes se rechaza", () => {
  const f = nueva();
  for (const m of [undefined, null, 123, "", "          ", "  error  ", "123456789", "  123456789  "]) {
    assert.throws(() => anularFactura(f, m), Error, `motivo ${JSON.stringify(m)}`);
  }
});

test("RF-005-d: la anulada está congelada, conserva montos y líneas; 10 caracteres exactos se aceptan", () => {
  const original = nueva();
  const a = anularFactura(original, "  1234567890  ");
  assert.equal(a.motivo, "1234567890");
  assert.ok(Object.isFrozen(a));
  assert.equal(a.totalCentavos, original.totalCentavos);
  assert.equal(a.ivaCentavos, original.ivaCentavos);
  assert.equal(a.netoCentavos, original.netoCentavos);
  assert.deepEqual(a.items, original.items);
});

test("RF-005-e: anular una factura ya anulada se rechaza", () => {
  const a = anularFactura(nueva(), "Error en el NIT del cliente");
  assert.throws(() => anularFactura(a, "Otro motivo suficientemente largo"), Error);
});
